// Tally webhook payload structure:
// body.data.fields = array of { key, label, type, value }
// Each field has a label (your form field name) and a value

const body = $input.first().json.body || $input.first().json;
const fields = body?.data?.fields || [];

// Helper: find field value by label (case-insensitive partial match)
function getField(labelSearch) {
  const match = fields.find(f =>
    f.label && f.label.toLowerCase().includes(labelSearch.toLowerCase())
  );
  if (!match) return null;
  // Tally returns arrays for some field types
  if (Array.isArray(match.value)) return match.value.join(', ');
  return match.value || null;
}

// Extract fields from your Tally form
const name    = getField('name');
const email   = getField('email');
const phone   = getField('phone');
const subject = getField('subject');
const message = getField('message') || getField('enquiry') || getField('question');

if (!message || message.trim().length === 0) {
  throw new Error('No enquiry message found in Tally submission');
}

// Build a clean enquiry string for Groq
let enquiryText = '';
if (name)    enquiryText += `From: ${name}`;
if (email)   enquiryText += ` <${email}>`;
if (phone)   enquiryText += ` | Phone: ${phone}`;
if (subject) enquiryText += `\nSubject: ${subject}`;
enquiryText += `\n\n${message}`;

return [{
  json: {
    enquiry_text:  enquiryText.trim(),
    sender_name:   name,
    sender_email:  email,
    sender_phone:  phone,
    subject:       subject,
    raw_message:   message,
    tally_form_id: body?.data?.formId || null,
    submission_id: body?.data?.submissionId || null,
    received_at:   new Date().toISOString()
  }
}];

const groqResponse = $input.first().json;
const intake = $('Parse Tally Fields').first().json;

let classification;
try {
  const content = groqResponse.choices[0].message.content;
  classification = JSON.parse(content);
} catch (e) {
  throw new Error('Failed to parse Groq response: ' + e.message);
}

const routingMap = {
  'New Client':       'New Business',
  'Support Request':  'Building Manager',
  'Complaint':        'Client Relations',
  'Billing / Finance':'Accounts',
  'General Question': 'Client Relations'
};

const isHighPriority = 
  classification.urgency === 'High' || 
  classification.enquiry_type === 'Complaint';

const primaryRoute = routingMap[classification.enquiry_type] || 'Client Relations';

return [{
  json: {
    ...intake,
    classification,
    primary_route:    primaryRoute,
    is_high_priority: isHighPriority,
    processed_at:     new Date().toISOString()
  }
}];

